func ge_zero(p *Ge) {
	fe_0(&p.X)
	fe_1(&p.Y)
	fe_1(&p.Z)
	fe_0(&p.T)
}

func ge_tobytes(s []byte, h *Ge) {
	var v2 [10]int32
	var v3 [10]int32
	var v4 [10]int32
	fe_invert(&v2, &h.Z)
	fe_mul(&v3, &h.X, &v2)
	fe_mul(&v4, &h.Y, &v2)
	fe_tobytes(s[:], &v4)
	v12 := fe_isodd(&v3)
	s[31] ^= byte(v12 << 7)
	clear(v2[:])
	clear(v3[:])
	clear(v4[:])
}

func ge_frombytes_neg_vartime(h *Ge, s []byte) int {
	fe_frombytes(&h.Y, s[:])
	fe_1(&h.Z)
	fe_sq(&h.T, &h.Y)
	fe_mul(&h.X, &h.T, &D)
	fe_sub(&h.T, &h.T, &h.Z)
	fe_add(&h.X, &h.X, &h.Z)
	fe_mul(&h.X, &h.T, &h.X)
	v28 := Invsqrt(&h.X, &h.X)
	if v28 == 0 {
		return -1
	}
	fe_mul(&h.X, &h.T, &h.X)
	v39 := fe_isodd(&h.X)
	if uint32(v39) == (uint32(s[31]) >> 7) {
		fe_neg(&h.X, &h.X)
	}
	fe_mul(&h.T, &h.X, &h.Y)
	return 0
}

func ge_cache(c *Ge_cached, p *Ge) {
	fe_add(&c.Yp, &p.Y, &p.X)
	fe_sub(&c.Ym, &p.Y, &p.X)
	fe_copy(&c.Z, &p.Z)
	fe_mul(&c.T2, &p.T, &D2)
}

