	fe_add(&v3, &p.Y, &p.X)
	fe_sub(&v4, &p.Y, &p.X)
	fe_mul(&v3, &v3, &q.Yp)
	fe_mul(&v4, &v4, &q.Ym)
	fe_add(&s.Y, &v3, &v4)
	fe_sub(&s.X, &v3, &v4)
	fe_add(&s.Z, &p.Z, &p.Z)
	fe_mul(&s.Z, &s.Z, &q.Z)
	fe_mul(&s.T, &p.T, &q.T2)
	fe_add(&v3, &s.Z, &s.T)
	fe_sub(&v4, &s.Z, &s.T)
	fe_mul(&s.T, &s.X, &s.Y)
	fe_mul(&s.X, &s.X, &v4)
	fe_mul(&s.Y, &s.Y, &v3)
	fe_mul(&s.Z, &v3, &v4)
